  let j = start;
  const n = input.length;
  while (j < n) {
    const c = input[j];
    if (/[0-9a-zA-Z.]/.test(c)) {
      j += 1;
      continue;
    }
    if ((c === '+' || c === '-') && j > start && /[eE]/.test(input[j - 1])) {
      j += 1;
      continue;
    }
    break;
  }
  return input.slice(start, j);
}

