/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  const peek = () => tokens[pos];

  const tokenText = (tok) => String(tok.value);

  const throwUnexpected = (tok) => {
    if (tok === undefined) throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
    throw new ExprError(`unexpected token '${tokenText(tok)}' at ${tok.index}`, tok.index);
  };

  const parseArgs = () => {
    // pos is positioned just after the opening '('
    const args = [];
    if (peek() && peek().type === 'rparen') {
      pos += 1;
      return args;
    }
    for (;;) {
      args.push(parseAdditive());
      if (peek() && peek().type === 'comma') {
        pos += 1;
        continue;
      }
      break;
    }
    if (peek() && peek().type === 'rparen') {
      pos += 1;
    } else {
      throwUnexpected(peek());
    }
    return args;
  };

  function parsePrimary() {
    const tok = peek();
    if (tok === undefined) throw new ExprError(`unexpected end of input at ${input.length}`, input.length);

    if (tok.type === 'number') {
      pos += 1;
      return { type: 'number', value: tok.value, index: tok.index };
    }

    if (tok.type === 'name') {
      pos += 1;
      if (peek() && peek().type === 'lparen') {
        pos += 1; // consume '('
        const args = parseArgs();
        return { type: 'call', name: tok.value, args, index: tok.index };
      }
      return { type: 'variable', name: tok.value, index: tok.index };
