      pos += 1;
      const node = parseAdditive();
      if (peek() && peek().type === 'rparen') {
        pos += 1;
        return node;
      }
      const at = peek() ? peek().index : input.length;
      throw new ExprError(`missing closing parenthesis at ${at}`, at);
    }

    throwUnexpected(tok);
  }

